<script setup lang="ts">
import type { ServiceRules } from '~/utils/after-sales'
const props = defineProps<{ modelValue: ServiceRules; kind: string }>()
const emit = defineEmits<{ 'update:modelValue': [value: ServiceRules] }>()
const r = computed({ get: () => props.modelValue, set: value => emit('update:modelValue', value) })
const units = ['DAY','WEEK','MONTH','YEAR'].map(value => ({ value, label: value[0]+value.slice(1).toLowerCase()+'s' }))
const activations = [{value:'DEFAULT',label:'Sale for POS / delivery for ecommerce'},{value:'SALE',label:'Sale date'},{value:'DELIVERY',label:'Delivery date'},{value:'INSTALLATION',label:'Installation date'},{value:'DATE',label:'Specific date'}]
function addField() { let i=r.value.fields.length+1;while(r.value.fields.some(f=>f.key==='field_'+i))i++;r.value.fields.push({key:'field_'+i,label:'',type:'TEXT',unit:'',required:false}) }
</script>
<template>
  <div class="space-y-6">
    <section class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><div><h3 class="text-sm font-semibold text-gray-900 dark:text-white">Activation</h3><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Choose when this plan starts for each client product.</p></div><div class="grid grid-cols-1 gap-4 sm:grid-cols-2">
      <UFormGroup label="Provider"><UInput v-model="r.provider" maxlength="200" placeholder="Store or manufacturer"/></UFormGroup><UFormGroup label="Starts from"><USelect v-model="r.activation" :options="activations"/></UFormGroup><UFormGroup v-if="r.activation==='DATE'" label="Start date" required><UInput v-model="r.startDate" type="date" required/></UFormGroup><UFormGroup label="Start offset" help="Leave as 0 to start on the selected date."><UInput v-model.number="r.offset" type="number" min="0" step="1"/></UFormGroup><UFormGroup label="Offset unit"><USelect v-model="r.offsetUnit" :options="units"/></UFormGroup>
    </div></section>
    <section v-if="kind!=='MAINTENANCE'" class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><h3 class="text-sm font-semibold">Coverage</h3><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><UFormGroup label="Coverage duration" required><UInput v-model.number="r.duration" type="number" min="1" required/></UFormGroup><UFormGroup label="Duration unit"><USelect v-model="r.durationUnit" :options="units"/></UFormGroup><UFormGroup label="Coverage and remedies" class="sm:col-span-2"><UTextarea v-model="r.coverage" :rows="3" placeholder="Describe what is covered and the available remedies"/></UFormGroup><UFormGroup label="Exclusions" class="sm:col-span-2"><UTextarea v-model="r.exclusions" :rows="2" placeholder="Describe what is excluded"/></UFormGroup></div></section>
    <section v-else class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><div><h3 class="text-sm font-semibold">Visit schedule</h3><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Maintenance continues independently of warranty or guarantee expiry.</p></div><div class="grid grid-cols-1 gap-4 sm:grid-cols-2">
      <UFormGroup label="Schedule"><USelect v-model="r.schedule" :options="[{value:'RECURRING',label:'Recurring'},{value:'ONCE',label:'One visit at start date'},{value:'CUSTOM',label:'Custom visit dates'}]"/></UFormGroup>
      <template v-if="r.schedule==='RECURRING'"><UFormGroup label="Repeat every" required><UInput v-model.number="r.interval" type="number" min="1" required/></UFormGroup><UFormGroup label="Frequency"><USelect v-model="r.frequency" :options="units"/></UFormGroup><UFormGroup label="Calculate next visit from"><USelect v-model="r.timing" :options="[{value:'CALENDAR',label:'Original calendar schedule'},{value:'COMPLETION',label:'Last completed service'}]"/></UFormGroup></template>
      <div v-if="r.schedule==='CUSTOM'" class="space-y-3 sm:col-span-2"><p class="text-sm font-medium">Visit dates</p><div v-for="(_,i) in r.dates" :key="i" class="flex items-center gap-2"><UInput v-model="r.dates[i]" type="date" required :aria-label="'Visit date '+(i+1)" class="w-full sm:max-w-xs"/><UButton type="button" color="gray" variant="ghost" icon="i-heroicons-trash" :aria-label="'Remove visit date '+(i+1)" @click="r.dates.splice(i,1)"/></div><UButton type="button" color="gray" variant="soft" icon="i-heroicons-plus" @click="r.dates.push('')">Add visit date</UButton></div>
      <UFormGroup label="End date" hint="Optional"><UInput v-model="r.endDate" type="date"/></UFormGroup><UFormGroup label="Completed-visit limit" hint="Optional"><UInput :model-value="r.visitLimit??''" type="number" min="1" @update:model-value="value=>r.visitLimit=value===''?null:Number(value)"/></UFormGroup><UFormGroup label="Included free visits"><UInput v-model.number="r.freeVisits" type="number" min="0"/></UFormGroup>
    </div></section>
    <section class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><h3 class="text-sm font-semibold">Charges and instructions</h3><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><UFormGroup label="Default charge before tax"><UInput v-model.number="r.charge" type="number" min="0" step="0.01"/></UFormGroup><UFormGroup label="Tax %"><UInput v-model.number="r.tax" type="number" min="0" max="100" step="0.01"/></UFormGroup><UFormGroup :label="kind==='MAINTENANCE'?'Maintenance rules and instructions':'Claim instructions'" class="sm:col-span-2"><UTextarea v-model="r.instructions" :rows="3" placeholder="Instructions for the staff handling this service"/></UFormGroup></div></section>
    <section class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><div><h3 class="text-sm font-semibold">Checklist</h3><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Tasks to check during a visit or claim assessment.</p></div><div v-for="(_,i) in r.checklist" :key="i" class="flex items-center gap-2"><UInput v-model="r.checklist[i]" placeholder="Check or task" :aria-label="'Checklist item '+(i+1)" class="flex-1"/><UButton type="button" color="gray" variant="ghost" icon="i-heroicons-trash" :aria-label="'Remove checklist item '+(i+1)" @click="r.checklist.splice(i,1)"/></div><UButton type="button" color="gray" variant="soft" icon="i-heroicons-plus" @click="r.checklist.push('')">Add checklist item</UButton></section>
    <section class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><div><h3 class="text-sm font-semibold">Custom readings and fields</h3><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Staff assess these manually. Only dates determine when a service is due.</p></div><div v-for="(f,i) in r.fields" :key="f.key" class="rounded-lg border border-gray-200 p-4 dark:border-gray-700"><div class="mb-3 flex items-center justify-between"><span class="text-xs font-medium text-gray-500 dark:text-gray-400">Field {{i+1}}</span><UButton type="button" color="gray" variant="ghost" icon="i-heroicons-trash" :aria-label="'Remove field '+(i+1)" @click="r.fields.splice(i,1)"/></div><div class="grid grid-cols-1 gap-4 sm:grid-cols-3"><UFormGroup label="Field label" required><UInput v-model="f.label" aria-label="Field label" placeholder="e.g. Meter reading" required/></UFormGroup><UFormGroup label="Answer type"><USelect v-model="f.type" aria-label="Field type" :options="[{value:'TEXT',label:'Text'},{value:'NUMBER',label:'Number'},{value:'DATE',label:'Date'},{value:'BOOLEAN',label:'Yes / No'}]"/></UFormGroup><UFormGroup label="Unit" hint="Optional"><UInput v-model="f.unit" placeholder="e.g. hours"/></UFormGroup><UCheckbox v-model="f.required" label="Required on completion" class="sm:col-span-3"/></div></div><UButton type="button" color="gray" variant="soft" icon="i-heroicons-plus" @click="addField">Add custom field</UButton></section>
    <section v-if="kind==='MAINTENANCE'" class="space-y-4 border-t border-gray-200 pt-6 dark:border-gray-800"><div><h3 class="text-sm font-semibold">Internal reminders</h3><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Days before the due date. Use 0 for a reminder on the day.</p></div><div v-for="(_,i) in r.reminderDays" :key="i" class="flex items-center gap-2"><UInput v-model.number="r.reminderDays[i]" type="number" min="0" max="365" :aria-label="'Reminder days '+(i+1)" class="w-32"/><span class="text-sm text-gray-500 dark:text-gray-400">days before</span><UButton type="button" color="gray" variant="ghost" icon="i-heroicons-trash" :aria-label="'Remove reminder '+(i+1)" @click="r.reminderDays.splice(i,1)"/></div><UButton type="button" color="gray" variant="soft" icon="i-heroicons-plus" @click="r.reminderDays.push(0)">Add reminder</UButton></section>
  </div>
</template>
